cd "/c/Users/eric_rash/Desktop/SecondBrain/Knowledge/library" && python - <<'PY'
import re,os,glob,collections
D="strength-and-conditioning/fundamentals-of-sprinting--moyer"
names={os.path.splitext(os.path.basename(p))[0] for p in glob.glob("**/*.md",recursive=True)}
files=[f for f in sorted(glob.glob(D+"/*.md")) if not f.endswith("_book.md")]
bych=collections.Counter(); conf=collections.Counter(); kinds=collections.Counter(); probs=[]
for f in files:
    t=open(f,encoding="utf-8").read(); b=os.path.basename(f)
    fm=re.match(r"---\n(.*?)\n---",t,re.S)
    if not fm: probs.append((b,"no frontmatter")); continue
    y=fm.group(1)
    g=lambda k:(re.search(rf"^{k}:\s*(.*)$",y,re.M) or [None,None])[1]
    for k in ["type","kind","domain","book","chapter","topic","category","confidence","ingest-tier","created"]:
        if g(k) is None: probs.append((b,"missing "+k))
    c=g("confidence"); conf[c]+=1; kinds[g("kind")]+=1
    if c not in ("supported","untested","contested"): probs.append((b,"conf="+str(c)))
    ch=re.match(r'"?(\d+)',g("chapter") or ""); bych[ch.group(1) if ch else "?"]+=1
    if g("kind") and not b.startswith(g("kind")+"--"): probs.append((b,"kind/filename mismatch"))
    for sec in ["**What it is**","**Why it works**","**When to apply**","**When NOT to apply**","**Example**"]:
        if sec not in t: probs.append((b,"missing "+sec))
    for l in re.findall(r"\[\[([^\]|#]+)",t):
        n=os.path.basename(l.strip())
        if n not in names: probs.append((b,"dangling [["+l+"]]"))
print(len(files),"entries"); print("by lesson",sorted(bych.items(),key=lambda x:int(x[0]) if x[0].isdigit() else 99))
print(conf); print(kinds); print("problems:"); [print(" ",p) for p in probs]
PY

